-- Verified geospatial / Earth-system degree catalogue seed.
-- Official university programme pages researched on 2026-10-08.
insert into public.courses
  (title, slug, degree_type, institution_id, language, duration, website, summary,
   verification_status, confidence, is_demo, last_verified_at)
select v.title, v.slug, v.degree_type, v.institution_id, v.language, v.duration,
       v.website, v.summary, 'auto_discovered', 'medium', false, now()
from (values
  ('Master Geomatics','eth-zurich-master-geomatics','Master','736670db-5621-46a1-b023-f1068e5bab45','English','2 years','https://ethz.ch/en/studies/master/degree-programmes/architecture-and-civil-engineering/geomatics.html','Master programme covering geographic information science, cartography, geodesy, navigation, surveying, geomonitoring, remote sensing and photogrammetry.'),
