  ('MPhil in Earth Sciences by Research Thesis','cambridge-mphil-earth-sciences','Master','c3933950-a1a7-454d-9b81-94db6cf01fdc','English','1 year','https://www.esc.cam.ac.uk/postgraduate','Research masters in Earth Sciences offered by Cambridge Earth Sciences.'),
  ('MPhil in Quantitative Climate and Environmental Science','cambridge-mphil-quantitative-climate-environmental-science','Master','c3933950-a1a7-454d-9b81-94db6cf01fdc','English','1 year','https://www.esc.cam.ac.uk/postgraduate','Cambridge masters programme in quantitative climate and environmental science.'),
